    @mcp.tool()
    def character_inventory_recharge(
        character_id: str,
        item_id: str,
        trigger: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Roll and apply one source-declared magic-item charge recovery."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "magic item recharge")
        if current.campaign_id is None:
            raise ValueError("magic item recharge requires a campaign-bound character")
        source_item = next(
            (
                item
                for item in current.sheet.get("inventory", {}).get("items", [])
                if str(item.get("id") or "") == item_id
            ),
            None,
        )
        if source_item is None or source_item.get("kind") != "magic_item":
            raise ValueError("item_id is not a magic item on this actor card")
        charge_rules = dict(dict(source_item.get("mechanics") or {}).get("charge_rules") or {})
        formula = str(charge_rules.get("recovery_formula") or "")
        if not formula:
            raise ValueError("magic item has no source-declared charge recovery")
        dice = asdict(roll(formula))
        applied = recharge_magic_item_charges(
            current.sheet,
            source_item_id=item_id,
            trigger=trigger,
            rolled_total=int(dice["total"]),
        )
        receipts = core_receipts(
            effective_rule_context(current.campaign_id),
            [CORE_MAGIC_ITEM_RECHARGE_MECHANIC_ID],
            "character.inventory.magic_item.recharge",
        )
        return update_sheet(
            character_id,
            applied["sheet"],
            operation="character.inventory.magic_item.recharge",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={"item_id": item_id, "trigger": trigger},
            response_extra={
                "recharge": {
                    key: value
                    for key, value in applied.items()
                    if key not in {"sheet", "rule_receipts"}
                }
                | {"roll": dice},
                "rule_receipts": receipts,
            },
            rule_receipts=receipts,
        )

    @mcp.tool()
    def character_ammunition_consume(
        character_id: str,
        weapon_id: str,
        quantity: int = 1,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Consume ammunition linked to a weapon through structured mechanics."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "ammunition consumption")
        sheet, consumed = consume_weapon_ammunition(current.sheet, weapon_id, quantity)
        return update_sheet(
            character_id,
            sheet,
            operation="character.ammunition.consume",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={"weapon_id": weapon_id, "quantity": quantity},
            response_extra={"consumed": consumed},
        )

    @mcp.tool()
    def character_inventory_transfer(
        source_character_id: str,
        target_character_id: str,
        item_id: str,
        quantity: int | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_campaign_revision: int | None = None,
        expected_source_revision: int | None = None,
        expected_target_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Move an inventory item between two actors in the same campaign."""
        payload = {
            "source_character_id": source_character_id,
            "target_character_id": target_character_id,
            "item_id": item_id,
            "quantity": quantity,
        }
        source = characters.get(source_character_id)
        target = characters.get(target_character_id)
        require_outside_active_combat(source, "inventory transfer")
        require_outside_active_combat(target, "inventory transfer")
        if source.campaign_id is None or source.campaign_id != target.campaign_id:
            raise ValueError("characters must belong to the same campaign")
        if (
            expected_campaign_revision is None
            or expected_source_revision is None
            or expected_target_revision is None
            or not idempotency_key
        ):
            raise ValueError(
                "expected_campaign_revision, expected_source_revision, "
                "expected_target_revision, and idempotency_key are required for inventory transfer"
            )
        branch_id = require_current_branch(source.campaign_id, None)
        payload["branch_id"] = branch_id
        scope = f"character-inventory:{source.campaign_id}:{branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        access.require_actor(source.campaign_id, source.id, principal_id, control=True)
        access.require_actor(source.campaign_id, target.id, principal_id, control=True)
        campaign = campaigns.get(source.campaign_id)
        source_sheet, moved = remove_inventory_item(source.sheet, item_id, quantity)
        moved = inventory_item_for_receipt(target.sheet, moved)
        target_sheet = receive_inventory_item(target.sheet, moved)
        source_sheet = finalize_actor_sheet_rulings(source_sheet, source.campaign_id)
        target_sheet = finalize_actor_sheet_rulings(target_sheet, target.campaign_id)
        source_after = replace(
            source,
            sheet=source_sheet,
            revision=source.revision + 1,
        )
        target_after = replace(
            target,
            sheet=target_sheet,
            revision=target.revision + 1,
        )
        response = commit_campaign_state(
            campaign,
            None,
            operation="character.inventory.transfer",
            principal_id=principal_id,
            branch_id=branch_id,
            idempotency_key=idempotency_key,
            scope=scope,
            payload=payload,
            response_fields={
                "source": visible_character_view(source_after, principal_id),
                "target": visible_character_view(target_after, principal_id),
                "item": moved,
            },
            character_updates=[
                CharacterStateUpdate(
                    source.id, source_sheet, source.notes, expected_source_revision
                ),
                CharacterStateUpdate(
                    target.id, target_sheet, target.notes, expected_target_revision
                ),
            ],
            include_campaign_revision=False,
            include_revisions=False,
            expected_campaign_revision=expected_campaign_revision,
        )
        return response

    @mcp.tool()
    def character_effect_add(
        character_id: str,
        effect: dict[str, Any],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Add a validated active D&D effect and return its assigned effect id."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "effect changes")
        sheet, effect_id = add_effect(current.sheet, effect)
        return update_sheet(
            character_id,
            sheet,
            operation="character.effect.add",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={"effect": effect},
            response_extra={"effect_id": effect_id},
        )

    @mcp.tool()
    def character_effect_remove(
        character_id: str,
        effect_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Remove an active D&D effect."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "effect changes")
        return update_sheet(
            character_id,
            remove_effect(current.sheet, effect_id),
            operation="character.effect.remove",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={"effect_id": effect_id},
        )

    def character_source_state_initialize(
        character_id: str,
        state: str,
        source_ref: str,
        reason: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Initialize a narrow adventure-authored actor state without fake events."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "source-authored state initialization")
        if current.campaign_id is None:
            raise ValueError("source-authored state requires a campaign-bound actor")
        access.require_campaign(current.campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        normalized_reason = str(reason).strip()
        if not normalized_reason or len(normalized_reason) > 1000:
            raise ValueError("source state reason must contain 1 to 1000 characters")
        normalized_ref = str(source_ref).strip()
        try:
            evidence = statblock_variant_evidence(
                current.campaign_id,
                {"source_ref": normalized_ref},
            )
        except (LookupError, NoResultFound) as exc:
            raise ValueError("source state source_ref must identify managed sources") from exc
        applied = initialize_source_state(current.sheet, state=state)
        result = {key: value for key, value in applied.items() if key != "sheet"}
        return update_sheet(
            character_id,
            applied["sheet"],
            operation="character.source_state.initialize",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={
                "state": result["source_state"],
                "source_ref": normalized_ref,
                "reason": normalized_reason,
            },
            response_extra={
                "result": result,
                "source_ref": normalized_ref,
                "source_evidence": evidence,
                "reason": normalized_reason,
            },
        )

    def campaign_stable_recovery(
        campaign_id: str,
        members: list[dict[str, Any]],
        resting_members: list[dict[str, Any]] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        branch_id: str | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Recover Stable creatures while conscious companions rest on the same clock."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_write_contract(expected_revision, idempotency_key)
        resolved_branch_id = require_current_branch(campaign_id, branch_id)
        if not isinstance(members, list) or not members:
            raise ValueError("stable recovery requires at least one member")
        normalized_members: list[dict[str, Any]] = []
        for index, member in enumerate(members):
            if not isinstance(member, dict):
                raise ValueError(f"members[{index}] must be an object")
            unknown = sorted(set(member) - {"character_id", "expected_revision"})
            character_id = str(member.get("character_id") or "").strip()
            character_revision = member.get("expected_revision")
            if unknown:
                raise ValueError(f"members[{index}] has unsupported fields: {unknown}")
            if not character_id:
                raise ValueError(f"members[{index}].character_id is required")
            if isinstance(character_revision, bool) or not isinstance(character_revision, int):
                raise ValueError(f"members[{index}].expected_revision is required")
            normalized_members.append(
                {
                    "character_id": character_id,
                    "expected_revision": character_revision,
                }
            )
        member_ids = [item["character_id"] for item in normalized_members]
        if len(member_ids) != len(set(member_ids)):
            raise ValueError("stable recovery member ids must be unique")
        if resting_members is None:
            resting_members = []
        if not isinstance(resting_members, list):
            raise ValueError("resting_members must be an array")
        allowed_resting_fields = {
            "character_id",
            "expected_revision",
            "rest_activity_minutes",
            "rest_schedule",
            "hit_dice_spends",
            "arcane_recovery",
            "natural_recovery",
            "sorcerous_restoration_points",
            "song_of_rest_source_actor_id",
            "attune_item_id",
            "attunement_prerequisite_confirmed",
        }
        normalized_resting: list[dict[str, Any]] = []
        for index, raw_member in enumerate(resting_members):
            if not isinstance(raw_member, dict):
                raise ValueError(f"resting_members[{index}] must be an object")
            unknown = sorted(set(raw_member) - allowed_resting_fields)
            if unknown:
                raise ValueError(
                    f"resting_members[{index}] has unsupported fields: {unknown}"
                )
            character_id = str(raw_member.get("character_id") or "").strip()
            character_revision = raw_member.get("expected_revision")
            if not character_id:
                raise ValueError(f"resting_members[{index}].character_id is required")
            if isinstance(character_revision, bool) or not isinstance(
                character_revision, int
            ):
                raise ValueError(
                    f"resting_members[{index}].expected_revision is required"
                )
            hit_dice_spends = raw_member.get("hit_dice_spends")
            arcane_recovery = raw_member.get("arcane_recovery")
            natural_recovery = raw_member.get("natural_recovery")
            sorcerous_restoration_points = raw_member.get(
                "sorcerous_restoration_points"
            )
            if hit_dice_spends is not None and not isinstance(hit_dice_spends, list):
                raise ValueError(
                    f"resting_members[{index}].hit_dice_spends must be an array"
                )
            if arcane_recovery is not None and not isinstance(arcane_recovery, dict):
                raise ValueError(
                    f"resting_members[{index}].arcane_recovery must be an object"
                )
            if natural_recovery is not None and not isinstance(natural_recovery, dict):
                raise ValueError(
                    f"resting_members[{index}].natural_recovery must be an object"
                )
            if sorcerous_restoration_points is not None and (
                isinstance(sorcerous_restoration_points, bool)
                or not isinstance(sorcerous_restoration_points, int)
            ):
                raise ValueError(
                    "resting_members["
                    f"{index}].sorcerous_restoration_points must be an integer"
                )
            attune_item_id = (
                str(raw_member.get("attune_item_id") or "").strip() or None
            )
            attunement_confirmed = raw_member.get(
                "attunement_prerequisite_confirmed"
            )
            if attune_item_id and attunement_confirmed is not True:
                raise NeedsRulingError(
                    "attunement requires explicit DM confirmation that the actor "
                    "satisfies every source-defined prerequisite",
                    missing=("attunement_prerequisite",),
                    ruling_kind="source_or_scene_fact",
                )
            if not attune_item_id and attunement_confirmed is not None:
                raise ValueError(
                    "attunement_prerequisite_confirmed requires attune_item_id"
                )
            normalized_resting.append(
                {
                    "character_id": character_id,
                    "expected_revision": character_revision,
                    "rest_activity_minutes": validate_rest_activity_minutes(
                        raw_member.get("rest_activity_minutes")
                    ),
                    "rest_schedule": deepcopy(raw_member.get("rest_schedule")),
                    "hit_dice_spends": list(hit_dice_spends or []),
                    "arcane_recovery": deepcopy(arcane_recovery or {}),
                    "natural_recovery": deepcopy(natural_recovery or {}),
                    "sorcerous_restoration_points": (
                        sorcerous_restoration_points
                    ),
                    "song_of_rest_source_actor_id": (
                        str(raw_member.get("song_of_rest_source_actor_id") or "").strip()
                        or None
                    ),
                    "attune_item_id": attune_item_id,
                    "attunement_prerequisite_confirmed": attunement_confirmed,
                }
            )
        resting_member_ids = [item["character_id"] for item in normalized_resting]
        if len(resting_member_ids) != len(set(resting_member_ids)):
            raise ValueError("resting member ids must be unique")
        if set(member_ids) & set(resting_member_ids):
            raise ValueError(
                "a stable recovery member cannot also complete a concurrent short rest"
            )
        song_source_ids = {
            str(item["song_of_rest_source_actor_id"])
            for item in normalized_resting
            if item["song_of_rest_source_actor_id"] is not None
        }
        if song_source_ids - set(resting_member_ids):
            raise CombatEngineError(
                "every Song of Rest source must participate in the concurrent short rest"
            )
        request_payload = {
            "operation": "campaign.party.stable_recovery",
            "members": deepcopy(normalized_members),
            "resting_members": deepcopy(normalized_resting),
            "branch_id": resolved_branch_id,
        }
        scope = f"campaign-stable-recovery:{campaign_id}:{resolved_branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay
        campaign = campaigns.get(campaign_id)
        if campaign.revision != expected_revision:
            raise ValueError(
                "campaign revision conflict: "
                f"expected {expected_revision}, found {campaign.revision}"
            )
        next_state = validate_party_state(deepcopy(campaign.state or {}))
        if bool(dict(next_state.get("combat") or {}).get("active")):
            raise CombatEngineError("stable recovery is not allowed while combat is active")
        all_characters = {item.id: item for item in characters.list(campaign_id=campaign_id)}
        member_by_id = {item["character_id"]: item for item in normalized_members}
        resting_by_id = {
            item["character_id"]: item for item in normalized_resting
        }
        for member in normalized_members:
            current = all_characters.get(member["character_id"])
            if current is None:
                raise ValueError(
                    f"stable recovery actor is not in this campaign: {member['character_id']}"
                )
            require_character_control(current, principal_id)
            if current.revision != member["expected_revision"]:
                raise ValueError(f"character revision conflict: {current.id}")
            recover_stable_creature(current.sheet, recovery_hours=1)
        for member in normalized_resting:
            current = all_characters.get(member["character_id"])
            if current is None:
                raise ValueError(
                    f"concurrent rest actor is not in this campaign: {member['character_id']}"
                )
            require_character_control(current, principal_id)
            if current.revision != member["expected_revision"]:
                raise ValueError(f"character revision conflict: {current.id}")
            validate_rest_hit_dice_requests(
                current.sheet,
                member["hit_dice_spends"],
            )
            validate_natural_recovery_choice(
                current.sheet,
                member["natural_recovery"],
                rest_activity_minutes=member["rest_activity_minutes"],
            )
            validate_sorcerous_restoration_choice(
                current.sheet,
                member["sorcerous_restoration_points"],
            )
            if member["song_of_rest_source_actor_id"] is not None:
                validate_song_of_rest_source(
                    all_characters[str(member["song_of_rest_source_actor_id"])].sheet
                )
            if member["attune_item_id"] is not None:
                attune_inventory_item(current.sheet, str(member["attune_item_id"]))

        recovery_rolls = {character_id: asdict(roll("1d4")) for character_id in member_ids}
        recovery_hours = {
            character_id: int(recovery_rolls[character_id]["total"]) for character_id in member_ids
        }
        elapsed_hours = max(recovery_hours.values())
        duration_minutes = elapsed_hours * 60
        started_elapsed_ticks = int(next_state["game_time"]["elapsed_ticks"])
        for member in normalized_resting:
            requested_schedule = member["rest_schedule"]
            if requested_schedule is None:
                requested_schedule = {
                    "sleep_minutes": 0,
                    "light_activity_minutes": duration_minutes,
                    "strenuous_activity_minutes": 0,
                }
            member["rest_schedule"] = validate_rest_schedule(
                rest_type="short_rest",
                duration_minutes=duration_minutes,
                rest_schedule=requested_schedule,
                allows_trance=False,
            )
            record_rest_completion(
                all_characters[member["character_id"]].sheet,
                rest_type="short_rest",
                started_elapsed_ticks=started_elapsed_ticks,
                completed_elapsed_ticks=started_elapsed_ticks
                + game_time_ticks("hour", elapsed_hours),
                rest_schedule=member["rest_schedule"],
            )
        next_state, time_transition = advance_state_game_time(
            next_state,
            period="hour",
            count=elapsed_hours,
        )
        next_world_time = time_transition["world_time_after"]
        elapsed_ticks = int(time_transition["elapsed_ticks"])
        elapsed_minutes = elapsed_ticks // TICKS_PER_MINUTE
        completed_game_day = rules_day_from_ticks(
            int(time_transition["after"]["elapsed_ticks"])
        )
        world_duration = advance_world_effect_clocks(
            next_state,
            elapsed_ticks=elapsed_ticks,
            period_steps={"round": elapsed_ticks},
        )
        next_state = world_duration["state"]
        world_advanced = world_duration["advanced"]
        world_expired = world_duration["expired"]

        rules = effective_rule_context(campaign_id)
        receipts: list[dict[str, Any]] = []
        updates: list[CharacterStateUpdate] = []
        advanced: dict[str, list[str]] = {}
        expired: dict[str, list[str]] = {}
        recoveries: dict[str, dict[str, Any]] = {}
        rested: dict[str, dict[str, Any]] = {}
        for current in all_characters.values():
            sheet = current.sheet
            character_advanced: list[str] = []
            character_expired: list[str] = []
            duration_result = advance_elapsed_effect_durations(
                sheet,
                elapsed_ticks=elapsed_ticks,
            )
            round_result = advance_effect_durations(
                duration_result["sheet"],
                period="round",
                amount=int(time_transition["elapsed_ticks"]),
            )
            extension = apply_rule_event(
                round_result["sheet"],
                "duration.advance",
                context_with_facts(
                    rules,
                    actor_id=current.id,
                    period="minute",
                    amount=elapsed_minutes,
                ),
            )
            receipts.extend(extension.receipts)
            sheet = extension.sheet
            character_advanced.extend(duration_result["advanced"])
            character_expired.extend(duration_result["expired"])
            character_advanced.extend(round_result["advanced"])
            character_expired.extend(round_result["expired"])
            member = member_by_id.get(current.id)
            if member is not None:
                applied = recover_stable_creature(sheet, recovery_hours=recovery_hours[current.id])
                sheet = applied["sheet"]
                recoveries[current.id] = {
                    "status": applied["status"],
                    "recovery_roll": recovery_rolls[current.id],
                    "recovery_hours": applied["recovery_hours"],
                    "before_hp": applied["before_hp"],
                    "after_hp": applied["after_hp"],
                }
                receipts.extend(
                    core_receipts(
                        effective_rule_context(
                            campaign_id,
                            facts={
                                "actor_id": current.id,
                                "recovery_hours": recovery_hours[current.id],
                            },
                        ),
                        ["dnd5e.core.damage.stable_recovery"],
                        "character.stable_recovery",
                    )
                )
            resting_member = resting_by_id.get(current.id)
            if resting_member is not None:
                rest_rules = effective_rule_context(
                    campaign_id,
                    facts={
                        "actor_id": current.id,
                        "rest_type": "short_rest",
                    },
                )
                song_source_id = resting_member["song_of_rest_source_actor_id"]
                applied_rest = apply_rest(
                    sheet,
                    rest_type="short_rest",
                    rest_activity_minutes=resting_member["rest_activity_minutes"],
                    rules=rest_rules,
                    game_day=completed_game_day,
                    hit_dice_spends=resting_member["hit_dice_spends"],
                    arcane_recovery=resting_member["arcane_recovery"],
                    natural_recovery=resting_member["natural_recovery"],
                    sorcerous_restoration_points=resting_member[
                        "sorcerous_restoration_points"
                    ],
                    song_of_rest_source_sheet=(
                        all_characters[str(song_source_id)].sheet
                        if song_source_id is not None
                        else None
                    ),
                )
                if applied_rest.get("status") != "committed":
                    raise CombatEngineError(
                        f"concurrent short rest for {current.id} requires "
                        "an unresolved rule choice"
                    )
                sheet = applied_rest["sheet"]
                if resting_member["attune_item_id"] is not None:
                    sheet = attune_inventory_item(
                        sheet,
                        str(resting_member["attune_item_id"]),
                    )
                    applied_rest["attuned_item_id"] = str(
                        resting_member["attune_item_id"]
                    )
                sheet = record_rest_completion(
                    sheet,
                    rest_type="short_rest",
                    started_elapsed_ticks=started_elapsed_ticks,
                    completed_elapsed_ticks=int(
                        time_transition["after"]["elapsed_ticks"]
                    ),
                    rest_schedule=resting_member["rest_schedule"],
                )
                rested[current.id] = {
                    key: value
                    for key, value in applied_rest.items()
                    if key not in {"sheet", "rule_receipts"}
                }
                receipts.extend(applied_rest.get("rule_receipts") or [])
            if sheet != current.sheet:
                updates.append(
                    CharacterStateUpdate(
                        character_id=current.id,
                        sheet=validate_character_sheet(sheet),
                        notes=validate_character_notes(current.notes),
                        expected_revision=(
                            member["expected_revision"] if member is not None else current.revision
                        ),
                    )
                )
            if character_advanced:
                advanced[current.id] = list(dict.fromkeys(character_advanced))
            if character_expired:
                expired[current.id] = list(dict.fromkeys(character_expired))
        update_by_id = {item.character_id: item for item in updates}
        stream = active_random_stream()
        response = {
            "status": "recovered",
            "member_ids": member_ids,
            "resting_member_ids": resting_member_ids,
            "elapsed_hours": elapsed_hours,
            "recoveries": recoveries,
            "rested": rested,
            "characters": {
                character_id: character_view(
                    replace(
                        all_characters[character_id],
                        sheet=update_by_id[character_id].sheet,
                        notes=update_by_id[character_id].notes,
                        revision=all_characters[character_id].revision + 1,
                    )
                )
                for character_id in member_ids
            },
            "game_time": time_transition["after"],
            "world_time": next_world_time,
            "advanced": advanced,
            "expired": expired,
            "world_advanced": list(dict.fromkeys(world_advanced)),
            "world_expired": list(dict.fromkeys(world_expired)),
            "rule_receipts": receipts,
            "campaign_revision": campaign.revision + 1,
            **(
                {"random_stream_receipt": stream.receipt()}
                if stream is not None and stream.draw_count > 0
                else {}
            ),
        }
        StateMutationService(storage.database).replace(
            campaign_id,
            campaign_state=next_state,
            character_updates=updates,
            expected_campaign_revision=campaign.revision,
            operation="campaign.party.stable_recovery",
            actor=principal_id,
            branch_id=resolved_branch_id,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=request_payload,
                response=response,
            ),
            rule_receipts=receipts,
        )
        return response

    def character_stand(
        character_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Stand a conscious Prone character outside active combat."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "standing")
        if current.campaign_id is None:
            raise ValueError("standing requires a campaign-bound character")
        applied = stand_outside_combat(current.sheet)
        rules = effective_rule_context(
            current.campaign_id, facts={"actor_id": character_id, "condition": "prone"}
        )
        receipts = core_receipts(
            rules,
            ["dnd5e.core.movement.prone_crawl_stand"],
            "character.stand",
        )
        return update_sheet(
            character_id,
            applied["sheet"],
            operation="character.stand",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={"operation": "stand"},
            response_extra={
                "status": applied["status"],
                "removed_condition": applied["removed_condition"],
                "rule_receipts": receipts,
            },
            rule_receipts=receipts,
        )

