    @mcp.tool()
    def combat_map_patch(
        campaign_id: str,
        patches: list[dict[str, Any]],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        branch_id: str | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Record Agent-as-DM-confirmed changes from a temporary battle map."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_write_contract(expected_revision, idempotency_key)
        resolved_branch_id = require_current_branch(campaign_id, branch_id)
        normalized: list[dict[str, Any]] = []
        for patch in patches:
            if not isinstance(patch, dict) or not isinstance(patch.get("key"), str):
                raise ValueError("each map patch needs a string key")
            normalized.append({"key": patch["key"], "value": deepcopy(patch.get("value"))})
        payload = {"patches": normalized, "branch_id": resolved_branch_id}
        scope = f"combat-map-patch:{campaign_id}:{resolved_branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        campaign, encounter = active_encounter(campaign_id)
        if campaign.revision != expected_revision:
            raise ValueError(
                "campaign revision conflict: "
                f"expected {expected_revision}, found {campaign.revision}"
            )
        battle_map = dict(encounter.get("battle_map") or {})
        if not battle_map:
            raise CombatEngineError("active encounter has no temporary battle map")
        next_encounter = deepcopy(encounter)
        next_map = patch_battle_map(dict(next_encounter["battle_map"]), normalized)
        next_encounter["battle_map"] = next_map
        participant_ids = {
            str(item.get("actor_id")) for item in next_encounter.get("combatants", [])
        }
        seen_visibility_actors: set[str] = set()
        seen_departure_actors: set[str] = set()
        for patch in normalized:
            if patch["key"] == "combatant_departure":
                departure = patch.get("value")
                if not isinstance(departure, dict) or set(departure) - {
                    "actor_id",
                    "reason",
                    "destination_location_key",
                }:
                    raise ValueError(
                        "combatant_departure requires actor_id, reason, and optional "
                        "destination_location_key"
                    )
                target_id = str(departure.get("actor_id") or "")
                if target_id not in participant_ids or target_id in seen_departure_actors:
                    raise ValueError(
                        "combatant_departure actor_id must be a unique encounter participant"
                    )
                seen_departure_actors.add(target_id)
                reason = str(departure.get("reason") or "").strip()
                if not reason:
                    raise ValueError(
                        "combatant_departure requires a source or Agent-as-DM ruling reason"
                    )
                destination = str(departure.get("destination_location_key") or "").strip()
                combatant = next(
                    item
                    for item in next_encounter["combatants"]
                    if str(item.get("actor_id")) == target_id
                )
                combatant["departed"] = {
                    "reason": reason,
                    "destination_location_key": destination,
                }
                combatant["hidden"] = True
                continue
            if patch["key"] != "combatant_visibility":
                continue
            visibility = patch.get("value")
            if not isinstance(visibility, dict) or set(visibility) - {
                "actor_id",
                "hidden",
                "visible_to_actor_ids",
                "reason",
            }:
                raise ValueError(
                    "combatant_visibility requires actor_id, reason, and optional "
                    "hidden/visible_to_actor_ids"
                )
            target_id = str(visibility.get("actor_id") or "")
            if target_id not in participant_ids or target_id in seen_visibility_actors:
                raise ValueError(
                    "combatant_visibility actor_id must be a unique encounter participant"
                )
            seen_visibility_actors.add(target_id)
            if not str(visibility.get("reason") or "").strip():
                raise ValueError("combatant_visibility requires an Agent-as-DM ruling reason")
            if "hidden" not in visibility and "visible_to_actor_ids" not in visibility:
                raise ValueError("combatant_visibility must change hidden or visible_to_actor_ids")
            if "hidden" in visibility and not isinstance(visibility["hidden"], bool):
                raise ValueError("combatant_visibility hidden must be boolean")
            visible_to = visibility.get("visible_to_actor_ids")
            if "visible_to_actor_ids" in visibility and visible_to is not None:
                if (
                    not isinstance(visible_to, list)
                    or len({str(item) for item in visible_to}) != len(visible_to)
                    or any(str(item) not in participant_ids for item in visible_to)
                ):
                    raise ValueError(
                        "combatant_visibility visible_to_actor_ids must be unique participants"
                    )
            combatant = next(
                item
                for item in next_encounter["combatants"]
                if str(item.get("actor_id")) == target_id
            )
            if "hidden" in visibility:
                combatant["hidden"] = visibility["hidden"]
            if "visible_to_actor_ids" in visibility:
                combatant["visible_to_actor_ids"] = (
                    None if visible_to is None else [str(item) for item in visible_to]
                )
        state = dict(campaign.state or {})
        state["combat"] = next_encounter
        runtime = dict(state.get("scene_runtime") or {})
        scene_id = str(dict(next_map.get("source") or {}).get("scene_id") or "")
        if scene_id:
            scene_state = dict(runtime.get(scene_id) or {})
            for patch in normalized:
                scene_state[patch["key"]] = patch["value"]
            runtime[scene_id] = scene_state
        state["scene_runtime"] = runtime
        response = commit_campaign_state(
            campaign,
            state,
            operation="combat.map.patch",
            principal_id=principal_id,
            branch_id=resolved_branch_id,
            idempotency_key=idempotency_key,
            scope=scope,
            payload=payload,
            response_fields={
                "battle_map": next_map,
                "world_patches": normalized,
                "combat": next_encounter,
            },
            include_revisions=False,
        )
        return response

    @mcp.tool()
    def combat_end(
        campaign_id: str,
        outcome: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        branch_id: str | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Close an encounter atomically while preserving its final audit state."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_write_contract(expected_revision, idempotency_key)
        campaign = campaigns.get(campaign_id)
        resolved_branch_id = require_current_branch(campaign_id, branch_id)
        outcome_value = dict(outcome or {})
        if outcome_value:
            allowed = {"status", "summary"}
            unknown = set(outcome_value) - allowed
            if unknown:
                raise ValueError(f"unsupported combat outcome fields: {sorted(unknown)}")
            status = str(outcome_value.get("status") or "").strip().lower()
            if status not in COMBAT_OUTCOME_STATUSES:
                raise ValueError("combat outcome status is invalid")
            summary = str(outcome_value.get("summary") or "").strip()
            if not summary or len(summary) > 2000:
                raise ValueError("combat outcome summary must contain 1 to 2000 characters")
            outcome_value = {"status": status, "summary": summary}
        payload = {"branch_id": resolved_branch_id, "outcome": outcome_value}
        scope = f"combat-end:{campaign_id}:{resolved_branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            replay_response = combat_response(campaign_id, principal_id, replay)
            replay_response["skill_plan"] = skill_plan_context(
                principal_id=principal_id,
                campaign_id=campaign_id,
                operation="combat_end:closed",
            )
            return replay_response
        if expected_revision is not None and campaign.revision != expected_revision:
            raise ValueError(
                "campaign revision conflict: "
                f"expected {expected_revision}, found {campaign.revision}"
            )
        retained_combat = dict(campaign.state or {}).get("combat")
        if not isinstance(retained_combat, dict) or not retained_combat:
            raise CombatEngineError("campaign has no retained combat")
        combat = deepcopy(retained_combat)
        encounter_rules_edition(campaign_id, combat)
        recovering_postcombat = not combat.get("active", False)
        retained_outcome = dict(combat.get("outcome") or {})
        if recovering_postcombat and (
            not retained_outcome or outcome_value != retained_outcome
        ):
            raise CombatEngineError(
                "postcombat cleanup requires the exact retained combat outcome"
            )
        require_no_blocking_pending(combat)
        ending_actor_ids = list(
            dict.fromkeys(
                str(item.get("actor_id") or "")
                for item in [
                    *list(combat.get("combatants") or []),
                    *list(combat.get("reinforcements") or []),
                ]
                if isinstance(item, dict) and str(item.get("actor_id") or "")
            )
        )
        ending_actors = {
            actor_id_value: characters.get(actor_id_value)
            for actor_id_value in ending_actor_ids
        }
        if not recovering_postcombat:
            for combatant in combat.get("combatants", []):
                if not combatant.get("death_saves", False):
                    continue
                actor = ending_actors[str(combatant["actor_id"])]
                hp = int(actor.sheet.get("combat", {}).get("hp", {}).get("value", 0) or 0)
                conditions = condition_ids(actor.sheet.get("conditions", []))
                if hp == 0 and not conditions & DEATH_SAVE_SETTLED_CONDITIONS:
                    raise CombatEngineError(
                        f"cannot end combat while {actor.id} is still making death saves"
                    )
            combat["active"] = False
            if outcome_value:
                combat["outcome"] = outcome_value
        unavailable_source_ids = {
            str(combatant.get("actor_id") or "")
            for combatant in combat.get("combatants", [])
            if isinstance(combatant, dict)
            and (
                combatant.get("departed") is not None
                or condition_ids(
                    ending_actors[str(combatant.get("actor_id") or "")].sheet.get(
                        "conditions", []
                    )
                )
                & INCAPACITATING_STATE_IDS
            )
        }
        released_grapples = release_unavailable_source_grapples(
            combat,
            unavailable_source_ids,
        )
        if recovering_postcombat and not released_grapples:
            raise CombatEngineError(
                "retained combat has no unavailable-source grapple cleanup to recover"
            )
        ending_readied = list(combat.get("readied", []))
        combat["readied"] = []
        updated_state = dict(campaign.state or {})
        updated_state["combat"] = combat
        updated_state["game_phase"] = PROFILE_PLAY
        character_updates: list[CharacterStateUpdate] = []
        expired_effects: set[str] = set()
        for actor_id_value in ending_actor_ids:
            if recovering_postcombat and actor_id_value not in released_grapples:
                continue
            actor = ending_actors[actor_id_value]
            sheet = deepcopy(actor.sheet)
            if not recovering_postcombat:
                for source_condition in combat.get("source_conditions", []):
                    if str(
                        source_condition.get("actor_id") or ""
                    ) != actor.id or not (
                        source_condition.get("active", True)
                        and source_condition.get("added_by_encounter", False)
                    ):
                        continue
                    condition = str(source_condition.get("condition") or "").casefold()
                    apply_condition_change(sheet, condition_id=condition, add=False)
                holding_ids = {
                    str(item.get("holding_effect_id"))
                    for item in ending_readied
                    if item.get("kind") == "spell" and item.get("actor_id") == actor.id
                }
                for effect in sheet.get("effects", []):
                    if str(effect.get("id")) in holding_ids:
                        effect["active"] = False
                advanced = expire_combat_bound_effects(sheet)
                expired_effects.update(advanced["expired"])
                sheet = advanced["sheet"]
            if actor_id_value in released_grapples and not has_active_owned_condition(
                combat,
                target_id=actor_id_value,
                condition="grappled",
            ):
                apply_condition_change(sheet, condition_id="grappled", add=False)
            normalized_sheet = validate_character_sheet(sheet)
            sync_combatant_conditions(combat, actor_id_value, normalized_sheet)
            character_updates.append(
                CharacterStateUpdate(
                    character_id=actor.id,
                    sheet=normalized_sheet,
                    notes=validate_character_notes(actor.notes),
                    expected_revision=actor.revision,
                )
            )
        updated_state["combat"] = combat
        response = commit_campaign_state(
            campaign,
            updated_state,
            operation=(
                "combat.end.cleanup" if recovering_postcombat else "combat.end"
            ),
            principal_id=principal_id,
            branch_id=resolved_branch_id,
            idempotency_key=idempotency_key,
            scope=scope,
            payload=payload,
            response_fields={
                "ended": True,
                "combat": combat,
                "outcome": outcome_value or retained_outcome or None,
                "tool_profile": PROFILE_PLAY,
                "recovered_postcombat_cleanup": recovering_postcombat,
                "released_grapples": {
                    target_id: sorted(effect_ids)
                    for target_id, effect_ids in released_grapples.items()
                },
                "effects_expired": sorted(expired_effects),
                "readied_spells_expired": sorted(
                    str(item.get("id")) for item in ending_readied if item.get("kind") == "spell"
                ),
            },
            character_updates=character_updates,
        )
        result = combat_response(campaign_id, principal_id, response)
        result["skill_plan"] = skill_plan_context(
            principal_id=principal_id,
            campaign_id=campaign_id,
            operation="combat_end:closed",
        )
        return result

    @mcp.tool()
    def continuity_context(
        campaign_id: str,
        query: str = "",
        actor_id: str | None = None,
        scope_id: str = "party",
        audience: str = "dm",
        purpose: Literal[
            "general",
            "npc_turn",
            "actor_turn",
            "audience_render",
            "faction_turn",
            "source_interpretation",
            "bounded_ruling",
        ] = "general",
        subject_ref: str | None = None,
        evaluation_target_refs: list[str] | None = None,
        interlocutor_actor_ids: list[str] | None = None,
        stimulus: dict[str, Any] | None = None,
        conversation_limit: int = 8,
        branch_id: str | None = None,
        limit: int = 8,
        budget_chars: int = 12_000,
        related_refs: list[str] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Retrieve current continuity plus pinned, source-exact DM module context."""
        continuity_purposes = NPC_TURN_PURPOSES | BOUNDED_EVALUATION_PURPOSES
        if purpose not in continuity_purposes:
            raise ValueError(f"unsupported continuity context purpose: {purpose}")
        live_turn_purposes = {
            "npc_turn",
            "actor_turn",
            "audience_render",
            "faction_turn",
        }
        if purpose in live_turn_purposes and authoritative_phase(campaign_id) not in {
            PROFILE_PLAY,
            PROFILE_COMBAT,
        }:
            raise ValueError(
                f"{purpose} context is available only during Play or Combat"
            )
        membership = access.require_campaign(campaign_id, principal_id)
        branch_id = readable_branch(campaign_id, branch_id, principal_id)
        if audience not in {"dm", "player"}:
            raise ValueError("audience must be dm or player")
        dm_only_purposes = {
            "npc_turn",
            "actor_turn",
            "faction_turn",
            "source_interpretation",
            "bounded_ruling",
        }
        if purpose in dm_only_purposes and membership.role not in CAMPAIGN_DM_ROLES:
            raise ValueError(f"{purpose} context is available only to Owner/DM")
        if purpose in {"npc_turn", "actor_turn"} and not actor_id:
            raise ValueError(f"actor_id is required for {purpose} context")
        if membership.role not in CAMPAIGN_DM_ROLES:
            audience = "player"
            scope_id = readable_scene_scope(campaign_id, scope_id, principal_id)
            if actor_id:
                access.require_actor(
                    campaign_id,
                    actor_id,
                    principal_id,
                    private=True,
                    branch_id=branch_id,
                )
        elif actor_id:
            access.require_actor(
                campaign_id,
                actor_id,
                principal_id,
                private=True,
                branch_id=branch_id,
            )
        if purpose == "audience_render" and audience != "player":
            raise ValueError("audience_render requires audience='player'")
        resolved_related_refs = {
            normalize_context_entity_ref(item, field="related_refs[]")
            for item in list(related_refs or [])
        }
        if actor_id:
            resolved_related_refs.add(f"actor:{actor_id}")
        normalized_interlocutor_ids: list[str] = []
        for item in interlocutor_actor_ids or []:
            value = str(item).strip()
            if not value:
                raise ValueError("interlocutor_actor_ids must not contain blank ids")
            if value in normalized_interlocutor_ids:
                raise ValueError("interlocutor_actor_ids must be unique")
            normalized_interlocutor_ids.append(value)
            resolved_related_refs.add(f"actor:{value}")
        normalized_target_refs: list[str] = []
        for item in evaluation_target_refs or []:
            value = normalize_context_entity_ref(
                item, field="evaluation_target_refs[]"
            )
            if value in normalized_target_refs:
                raise ValueError("evaluation_target_refs must be unique")
            normalized_target_refs.append(value)
            resolved_related_refs.add(value)
        normalized_subject_ref: str | None = None
        if subject_ref is not None:
            normalized_subject_ref = normalize_context_entity_ref(
                subject_ref, field="subject_ref"
            )
            resolved_related_refs.add(normalized_subject_ref)
        if membership.role in CAMPAIGN_DM_ROLES:
            campaign = campaigns.get(campaign_id)
            state = dict(campaign.state or {})
            combat = dict(state.get("combat") or {})
            if combat.get("active", False):
                for combatant in [
                    *list(combat.get("combatants") or []),
                    *list(combat.get("reinforcements") or []),
                ]:
                    combat_actor_id = str(
                        dict(combatant or {}).get("actor_id") or ""
                    ).strip()
                    if combat_actor_id:
                        resolved_related_refs.add(f"actor:{combat_actor_id}")
            manifest = dict(state.get("playthrough_manifest") or {})
            current = dict(manifest.get("current") or {})
            if current_scene_id := str(current.get("scene_id") or "").strip():
                resolved_related_refs.add(f"scene:{current_scene_id}")
            if current_module_id := str(current.get("module_id") or "").strip():
                resolved_related_refs.add(f"module:{current_module_id}")
            for quest in list(manifest.get("quests") or []):
                quest_value = dict(quest or {})
                if str(quest_value.get("status") or "") != "active":
                    continue
                quest_id = str(quest_value.get("id") or "").strip()
                if quest_id:
                    resolved_related_refs.add(f"quest:{quest_id}")
        result = continuity.context(
            campaign_id,
            query=query,
            actor_id=actor_id,
            scope_id=scope_id,
            audience=audience,
            branch_id=branch_id,
            limit=limit,
            budget_chars=budget_chars,
            related_refs=sorted(resolved_related_refs),
        )
        if purpose in BOUNDED_EVALUATION_PURPOSES:
            return bounded_evaluation_bundle(
                purpose=purpose,
                campaign_id=campaign_id,
                branch_id=branch_id,
                principal_id=principal_id,
                role=membership.role,
                audience=audience,
                actor_id=actor_id,
                subject_ref=normalized_subject_ref,
                target_refs=normalized_target_refs,
                query=query,
                result=result,
                related_refs=resolved_related_refs,
                interlocutor_actor_ids=normalized_interlocutor_ids,
                stimulus=stimulus,
            )
        if purpose == "npc_turn":
            assert actor_id is not None
            actor = characters.get(actor_id)
            if actor.campaign_id != campaign_id:
                raise ValueError("NPC turn actor belongs to another campaign")
            if actor.character_type not in NON_PLAYER_CHARACTER_TYPES:
                raise ValueError("NPC turn actor must be an NPC or monster")
            if actor_id in normalized_interlocutor_ids:
                raise ValueError("NPC turn actor cannot also be an interlocutor")
            interlocutors: list[dict[str, Any]] = []
            for interlocutor_id in normalized_interlocutor_ids:
                interlocutor = characters.get(interlocutor_id)
                if interlocutor.campaign_id != campaign_id:
                    raise ValueError("every NPC interlocutor must belong to the campaign")
                interlocutors.append(
                    {
                        "id": interlocutor.id,
                        "name": interlocutor.name,
                        "character_type": interlocutor.character_type,
                    }
                )
            normalized_stimulus = normalize_npc_stimulus(stimulus)
            stimulus_actor_ids = {
                str(normalized_stimulus.get("speaker_actor_id") or ""),
                *normalized_stimulus.get("target_actor_ids", []),
            } - {""}
            allowed_stimulus_actor_ids = {actor_id, *normalized_interlocutor_ids}
            if unknown_stimulus_actors := sorted(
                stimulus_actor_ids - allowed_stimulus_actor_ids
            ):
                raise ValueError(
                    "stimulus actor ids must identify the NPC or an interlocutor: "
                    + ", ".join(unknown_stimulus_actors)
                )
            scene = npc_turn_scene_projection(result.get("scoped_scene"))
            perception = npc_turn_perception_projection(
                campaigns.get(campaign_id),
                actor_id=actor_id,
                interlocutors=interlocutors,
                scene=scene,
            )
            actor_state, fact_heads, knowledge_heads = npc_turn_actor_state(
                campaign_id,
                branch_id,
                actor_id,
            )
            relationships = [
                item for item in actor_state if item.get("predicate") == "relationship_to"
            ]
            goals = [item for item in actor_state if item.get("predicate") == "goal"]
            actor_knowledge = list(result.get("actor_knowledge") or [])
            common_context = [
                item
                for item in list(result.get("facts") or [])
                if item.get("disclosure_scope") == "public"
            ]
            relevant_anchor_heads = {
                str(item.id): str(item.revision_id)
                for item in memories.list(
                    campaign_id,
                    kind="context_anchor",
                    branch_id=branch_id,
                )
                if resolved_related_refs
                & {
                    str(ref)
                    for ref in list(dict(item.metadata or {}).get("related_refs") or [])
                }
            }
            context_fact_heads = {
                **relevant_anchor_heads,
                **{
                    str(item["id"]): str(item["revision_id"])
                    for item in common_context
                },
            }
            raw_conversation = events.list_for_actor(
                campaign_id,
                actor_id=actor_id,
                branch_id=branch_id,
                limit=max(1, min(int(conversation_limit), 30)),
            )
            conversation_window = []
            for event in raw_conversation:
                payload = dict(event.payload or {})
                conversation_window.append(
                    {
                        "event_id": event.id,
                        "sequence": event.sequence,
                        "event_type": event.event_type,
                        "summary": event.summary,
                        "speaker_actor_id": str(payload.get("speaker_actor_id") or ""),
                        "listener_actor_ids": list(payload.get("listener_actor_ids") or []),
                        "utterance": str(payload.get("utterance") or ""),
                        "language": str(payload.get("language") or ""),
                        "visible_action": str(payload.get("visible_action") or ""),
                        "participants": [dict(item) for item in event.participants],
                    }
                )
            stimulus_ref = "stimulus:" + hashlib.sha256(
                canonical_json(normalized_stimulus).encode("utf-8")
            ).hexdigest()
            allowed_basis_refs = {
                f"actor:{actor_id}:identity",
                f"actor:{actor_id}:self_state",
                *(
                    [stimulus_ref]
                    if normalized_stimulus.get("kind") != "none"
                    else []
                ),
                *(
                    f"knowledge:{item['id']}:{item['revision_id']}"
                    for item in actor_knowledge
                ),
                *(
                    f"fact:{item['id']}:{item['revision_id']}"
                    for item in actor_state
                ),
                *(str(item["basis_ref"]) for item in perception),
                *(f"event:{item['event_id']}" for item in conversation_window),
            }
            portrayal_context = [
                {
                    **dict(item),
                    "context_role": "dm_portrayal_context",
                    "disclosure_policy": "not_speakable_without_actor_basis",
                }
                for item in list(result.get("module_evidence") or [])
            ]
            branch = dict(result.get("branch") or {})
            bundle: dict[str, Any] = {
                "schema_version": NPC_TURN_SCHEMA_VERSION,
                "bundle_id": str(uuid4()),
                "purpose": "npc_turn",
                "authority": {
                    "campaign_id": campaign_id,
                    "branch_id": branch_id,
                    "head_snapshot_id": branch.get("head_snapshot_id"),
                    "campaign_revision": campaigns.get(campaign_id).revision,
                    "latest_event_sequence": npc_turn_latest_event_sequence(
                        campaign_id, branch_id
                    ),
                    "actor_revision": actor.revision,
                    "scene_state_version": int((scene or {}).get("state_version") or 0),
                    "host_context_binding": host_context_binding(
                        campaign_id=campaign_id,
                        branch_id=branch_id,
                        principal_id=principal_id,
                        role=membership.role,
                        audience=audience,
                    ),
                },
                "actor": npc_turn_actor_projection(actor),
                "interlocutors": interlocutors,
                "stimulus": {**normalized_stimulus, "basis_ref": stimulus_ref},
                "perception": perception,
                "actor_knowledge": actor_knowledge,
                "common_context": common_context,
                "relationships": relationships,
                "goals": goals,
                "conversation_window": conversation_window,
                "scene": scene,
                "portrayal_context": portrayal_context,
                "constraints": {
                    "allowed_basis_refs": sorted(allowed_basis_refs),
                    "allowed_target_actor_ids": sorted(
                        {actor_id, *normalized_interlocutor_ids}
                    ),
                    "module_evidence_is_actor_knowledge": False,
                    "common_context_is_actor_knowledge": False,
                    "may_roll_dice": False,
                    "may_call_tools": False,
                    "may_write_state": False,
                    "output_contract": "npc-turn-proposal.v1",
                },
                "retrieval": {
                    **dict(result.get("retrieval") or {}),
                    "actor_state_count": len(actor_state),
                    "conversation_event_count": len(conversation_window),
                },
            }
            receipt = issue_npc_turn_receipt(
                bundle=bundle,
                campaign_id=campaign_id,
                branch_id=branch_id,
                principal_id=principal_id,
                actor_id=actor_id,
                actor_revision=actor.revision,
                interlocutor_actor_ids=normalized_interlocutor_ids,
                scene=scene,
                fact_heads=fact_heads,
                context_fact_heads=context_fact_heads,
                knowledge_heads=knowledge_heads,
                allowed_basis_refs=sorted(allowed_basis_refs),
                stimulus=normalized_stimulus,
                module_evidence=portrayal_context,
            )
            bundle["bundle_receipt"] = receipt
            return bundle
        result["host_context_binding"] = host_context_binding(
            campaign_id=campaign_id,
            branch_id=branch_id,
            principal_id=principal_id,
            role=membership.role,
            audience=audience,
        )
        result["context_receipt"] = issue_context_receipt(
            campaign_id=campaign_id,
            branch_id=branch_id,
            principal_id=principal_id,
            audience=audience,
            actor_id=actor_id,
            scope_id=scope_id,
            related_refs=sorted(resolved_related_refs),
            context=result,
        )
        return result

    @mcp.tool()
    def bounded_evaluation(
        campaign_id: str,
        action: Literal["validate"],
        proposal: dict[str, Any],
        bundle_receipt: dict[str, Any],
        branch_id: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Validate one isolated proposal against its live signed context receipt."""

        if action != "validate":
            raise ValueError("bounded_evaluation action must be validate")
        membership = access.require_campaign(campaign_id, principal_id)
        branch_id = readable_branch(campaign_id, branch_id, principal_id)
        receipt = verify_bounded_evaluation_receipt(
            bundle_receipt,
            campaign_id=campaign_id,
            branch_id=branch_id,
            principal_id=principal_id,
        )
        purpose = str(receipt["purpose"])
        if membership.role not in CAMPAIGN_DM_ROLES and purpose != "audience_render":
            raise ValueError(
                "players may validate only audience_render proposals issued to themselves"
            )
        normalized = normalize_bounded_proposal(purpose, proposal)
        if normalized["bundle_id"] != receipt.get("bundle_id"):
            raise ValueError("bounded proposal belongs to another context bundle")
        if purpose == "source_interpretation" and hashlib.sha256(
            str(normalized["question"]).strip().encode("utf-8")
        ).hexdigest() != str(receipt.get("question_digest") or ""):
            raise ValueError(
                "source interpretation question does not match its signed bundle"
            )
        validate_bounded_proposal_refs(
            normalized,
            subject_ref=str(receipt["subject_ref"]),
            allowed_basis_refs={
                str(item) for item in receipt.get("allowed_basis_refs") or []
            },
            allowed_claim_basis_refs={
                str(item)
                for item in receipt.get("allowed_claim_basis_refs") or []
            },
            allowed_target_refs={
                str(item) for item in receipt.get("allowed_target_refs") or []
            },
        )
        proposal_digest = hashlib.sha256(
            canonical_json(normalized).encode("utf-8")
        ).hexdigest()
        validation_payload = {
            "schema_version": 1,
            "purpose": purpose,
            "bundle_id": str(receipt["bundle_id"]),
            "bundle_digest": str(receipt["bundle_digest"]),
            "proposal_digest": proposal_digest,
            "campaign_id": campaign_id,
            "branch_id": branch_id,
            "campaign_revision": campaigns.get(campaign_id).revision,
            "principal_fingerprint": receipt_principal_fingerprint(principal_id),
            "expires_monotonic_ns": int(receipt["expires_monotonic_ns"]),
        }
        validation_receipt = {
            **validation_payload,
            "signature": hmac.new(
                context_receipt_secret,
                canonical_json(validation_payload).encode("utf-8"),
                hashlib.sha256,
            ).hexdigest(),
        }
        result: dict[str, Any] = {
            "validated": True,
            "authoritative_state_changed": False,
            "purpose": purpose,
            "proposal": normalized,
            "validation_receipt": validation_receipt,
            "next_step": (
                "relay publication.text exactly"
                if purpose == "audience_render"
                else "resolve mechanics and select any writes through public MCP tools"
            ),
        }
        if purpose == "audience_render":
            result["publication"] = {
                "text": str(normalized["text"]),
                "validation_receipt": validation_receipt,
            }
        return result

    @mcp.tool()
    def continuity_diagnostics(
        campaign_id: str,
        branch_id: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Inspect continuity health without returning secret narrative content."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        branch_id = readable_branch(campaign_id, branch_id, principal_id)
        result = continuity.diagnostics(campaign_id, branch_id=branch_id)
        current_manifest = catalog.manifest()
        latest_manifest = None
        for item in reversed(events.list(campaign_id, limit=500, branch_id=branch_id)):
            candidate = item.payload.get("_sagasmith_skill_manifest")
            if isinstance(candidate, list):
                latest_manifest = candidate
                break
        result["skill_manifest"] = {
            "current": current_manifest,
            "latest_event": latest_manifest,
            "drift": (latest_manifest != current_manifest if latest_manifest is not None else None),
        }
        latest_slot = result["snapshots"]["latest_slot"]
        recap = snapshots.get(campaign_id, latest_slot).get("recap") if latest_slot else None
        provenance = dict(recap.get("provenance") or {}) if isinstance(recap, dict) else {}
        result["recap"] = {
            "schema_version": recap.get("schema_version") if isinstance(recap, dict) else None,
            "source": recap.get("source") if isinstance(recap, dict) else None,
            "has_presentation": bool(
                isinstance(recap, dict) and recap.get("presentation") is not None
            ),
            "evidence_event_count": len(provenance.get("evidence_event_ids") or []),
        }
        return result

    @mcp.tool()
    def continuity_commit(
        campaign_id: str,
        payload: dict[str, Any],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Atomically save a scene event, fact changes, actor knowledge, and snapshot."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for continuity commits")
        data = facade_payload(payload)
        branch_id = require_current_branch(campaign_id, data.get("branch_id"))
        raw_event = required(data, "event")
        raw_facts = data.get("facts") or []
        raw_knowledge = data.get("actor_knowledge") or []
        if not isinstance(raw_event, dict):
            raise ValueError("payload.event must be an object")
        if not isinstance(raw_facts, list) or not all(isinstance(item, dict) for item in raw_facts):
            raise ValueError("payload.facts must be a list of objects")
        if not isinstance(raw_knowledge, list) or not all(
            isinstance(item, dict) for item in raw_knowledge
        ):
            raise ValueError("payload.actor_knowledge must be a list of objects")
        event_data = dict(raw_event)
        facts_data = [dict(item) for item in raw_facts]
        knowledge_data = [dict(item) for item in raw_knowledge]
        context_receipt = data.get("context_receipt")
        npc_turn_data = data.get("npc_turn")
        npc_turn_receipt: dict[str, Any] | None = None
        npc_turn_trace: dict[str, Any] | None = None
        if npc_turn_data is not None:
            if not isinstance(npc_turn_data, dict):
                raise ValueError("payload.npc_turn must be an object")
            unknown_npc_fields = set(npc_turn_data) - {
                "bundle_receipt",
                "proposal",
                "accepted_fact_indexes",
                "accepted_actor_knowledge_indexes",
                "accepted_action",
                "isolation_level",
            }
            if unknown_npc_fields:
                raise ValueError(
                    f"payload.npc_turn has unknown fields: {sorted(unknown_npc_fields)}"
                )
            if facts_data or knowledge_data:
                raise ValueError(
                    "NPC turn facts and ActorKnowledge must come from accepted proposal indexes"
                )
            proposal = normalize_npc_turn_proposal(npc_turn_data.get("proposal"))
            npc_turn_receipt = verify_npc_turn_receipt(
                npc_turn_data.get("bundle_receipt"),
                campaign_id=campaign_id,
                branch_id=branch_id,
                principal_id=principal_id,
                require_fresh=False,
            )
            if proposal["bundle_id"] != npc_turn_receipt.get("bundle_id"):
                raise ValueError("NPC proposal belongs to another context bundle")
            if proposal["speaker_actor_id"] != npc_turn_receipt.get("actor_id"):
                raise ValueError("NPC proposal speaker does not match its context bundle")
            validate_npc_basis_refs(
                proposal,
                allowed_basis_refs={
                    str(item) for item in npc_turn_receipt.get("allowed_basis_refs") or []
                },
            )
            validate_npc_targets(
                proposal,
                allowed_actor_ids={
                    str(npc_turn_receipt["actor_id"]),
                    *(
                        str(item)
                        for item in npc_turn_receipt.get("interlocutor_actor_ids") or []
                    ),
                },
            )
            if proposal["resolution_requests"]:
                raise ValueError(
                    "NPC proposal requires resolution; use public rules tools and read a new bundle"
                )
            fact_indexes = npc_turn_data.get("accepted_fact_indexes") or []
            knowledge_indexes = npc_turn_data.get("accepted_actor_knowledge_indexes") or []
            if not isinstance(fact_indexes, list) or not isinstance(knowledge_indexes, list):
                raise ValueError("accepted NPC proposal indexes must be lists")
            facts_data, knowledge_data = accepted_proposal_deltas(
                proposal,
                fact_indexes=fact_indexes,
                actor_knowledge_indexes=knowledge_indexes,
            )
            speaker_actor_id = str(npc_turn_receipt["actor_id"])
            listener_actor_ids = [
                str(item) for item in npc_turn_receipt.get("interlocutor_actor_ids") or []
            ]
            allowed_delta_actor_ids = {speaker_actor_id, *listener_actor_ids}
            allowed_fact_fields = {
                "action",
                "fact_key",
                "memory_id",
                "content",
                "kind",
                "subject",
                "metadata",
                "subject_ref",
                "predicate",
                "status",
                "valid_from",
                "valid_to",
                "source_event_ids",
                "importance",
                "disclosure_scope",
                "expected_revision_id",
            }
            for index, fact in enumerate(facts_data):
                if unknown := set(fact) - allowed_fact_fields:
                    raise ValueError(
                        f"accepted NPC fact[{index}] has unknown fields: {sorted(unknown)}"
                    )
                if str(fact.get("kind") or "") != "actor_state":
                    raise ValueError("accepted NPC facts must use kind='actor_state'")
                if str(fact.get("subject_ref") or "") != f"actor:{speaker_actor_id}":
                    raise ValueError("accepted NPC facts must belong to the speaking actor")
                if str(fact.get("predicate") or "") not in {"relationship_to", "goal"}:
                    raise ValueError(
                        "accepted NPC facts may update only relationships or goals"
                    )
                if str(fact.get("disclosure_scope") or "dm") != "dm":
                    raise ValueError("accepted NPC actor-state facts must remain DM-only")
                fact["disclosure_scope"] = "dm"
            allowed_knowledge_fields = {
                "action",
                "actor_id",
                "knowledge_key",
                "knowledge_id",
                "proposition",
                "subject_ref",
                "epistemic_status",
                "confidence",
                "cause",
                "disclosure_scope",
                "expected_revision_id",
            }
            for index, item in enumerate(knowledge_data):
                if unknown := set(item) - allowed_knowledge_fields:
                    raise ValueError(
                        "accepted NPC ActorKnowledge"
                        f"[{index}] has unknown fields: {sorted(unknown)}"
                    )
                if str(item.get("actor_id") or "") not in allowed_delta_actor_ids:
                    raise ValueError(
                        "accepted NPC ActorKnowledge may target only the speaker or listeners"
                    )
            raw_accepted_action = npc_turn_data.get("accepted_action", False)
            if not isinstance(raw_accepted_action, bool):
                raise ValueError("payload.npc_turn.accepted_action must be boolean")
            accepted_action = raw_accepted_action
            action_kind = str(proposal["proposed_action"]["kind"])
            if accepted_action and action_kind not in NPC_NARRATIVE_ACTION_KINDS:
                raise ValueError(
                    "mechanical NPC actions require public engine tools before continuity commit"
                )
            action_target_ref = str(proposal["proposed_action"].get("target_ref") or "")
            if accepted_action and action_target_ref:
                allowed_action_targets = {
                    f"actor:{actor_id_value}" for actor_id_value in allowed_delta_actor_ids
                }
                if action_target_ref not in allowed_action_targets:
                    raise ValueError(
                        "accepted narrative NPC action target must be the speaker or listener"
                    )
            isolation_level = str(npc_turn_data.get("isolation_level") or "logical")
            if isolation_level not in {"isolated", "logical"}:
                raise ValueError("NPC turn isolation_level must be isolated or logical")
            audience_scope = str(event_data.get("audience_scope") or "actor")
            if audience_scope not in {"actor", "party", "public"}:
                raise ValueError("NPC dialogue audience_scope must be actor, party, or public")
            summary = str(event_data.get("summary") or "").strip()
            if not summary:
                raise ValueError("payload.event.summary is required")
            proposal_digest = hashlib.sha256(
                canonical_json(proposal).encode("utf-8")
            ).hexdigest()
            visible_action = ""
            if accepted_action and action_kind != "none":
                visible_action = str(proposal["proposed_action"].get("summary") or action_kind)
            npc_turn_trace = {
                "bundle_digest": str(npc_turn_receipt["bundle_digest"]),
                "proposal_digest": proposal_digest,
                "isolation_level": isolation_level,
            }
            event_data = {
                "event_type": "npc_dialogue_turn",
                "summary": summary,
                "audience_scope": audience_scope,
                "participants": [
                    {"actor_id": speaker_actor_id, "role": "speaker"},
                    *(
                        {"actor_id": listener_id, "role": "listener"}
                        for listener_id in listener_actor_ids
                    ),
                ],
                "payload": {
                    "schema_version": NPC_TURN_SCHEMA_VERSION,
                    "speaker_actor_id": speaker_actor_id,
                    "listener_actor_ids": listener_actor_ids,
                    "scene_id": str(npc_turn_receipt.get("scene_id") or ""),
                    "language": str(proposal["utterance"].get("language") or ""),
                    "utterance": str(proposal["utterance"].get("text") or ""),
                    "delivery": str(proposal["utterance"].get("delivery") or ""),
                    "visible_action": visible_action,
                    "turn_trace": npc_turn_trace,
                },
            }
            context_receipt = npc_turn_data.get("bundle_receipt")
        snapshot_data = dict(data["snapshot"]) if data.get("snapshot") is not None else None
        validate_embedded_module_source_refs(
            campaign_id,
            event_data.get("payload") or {},
            field="payload.event.payload",
        )
        validate_embedded_module_source_refs(
            campaign_id,
            facts_data,
            field="payload.facts",
        )
        validate_embedded_module_source_refs(
            campaign_id,
            knowledge_data,
            field="payload.actor_knowledge",
        )
        if (
            event_data.get("audience_scope") == "actor"
            and not knowledge_data
            and not event_data.get("participants")
        ):
            raise ValueError(
                "actor-scoped continuity events require ActorKnowledge or event participants"
            )
        manifest = catalog.manifest()
        for fact in facts_data:
            validate_subject_context_fact(
                kind=fact.get("kind"),
                subject_ref=fact.get("subject_ref"),
            )
        event_payload = dict(event_data.get("payload") or {})
        event_payload["_sagasmith_skill_manifest"] = manifest
        event_data["payload"] = event_payload
        # A response-lost retry normally carries the current post-commit
        # revision. Keep concurrency tokens out of the logical request hash so
        # the original atomic response can be replayed without duplicating it.
        request_payload = {
            "event": event_data,
            "facts": facts_data,
            "actor_knowledge": knowledge_data,
            "snapshot": snapshot_data,
            "branch_id": branch_id,
            "skill_manifest": manifest,
            "npc_turn_trace": npc_turn_trace,
        }
        scope = f"continuity-commit:{campaign_id}:{branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay
        embedded_source_digests = managed_module_source_digests(
            [event_data.get("payload") or {}, facts_data, knowledge_data]
        )
        required_source_digests = embedded_source_digests & anchored_source_digests(
            campaign_id,
            branch_id,
        )
        if npc_turn_receipt is not None:
            npc_turn_receipt = verify_npc_turn_receipt(
                context_receipt,
                campaign_id=campaign_id,
                branch_id=branch_id,
                principal_id=principal_id,
                required_source_digests=required_source_digests,
            )
        elif required_source_digests:
                verify_context_receipt(
                    context_receipt,
                    campaign_id=campaign_id,
                    branch_id=branch_id,
                    principal_id=principal_id,
                    required_source_digests=required_source_digests,
                )
        current_facts = {
            item.fact_key: item
            for item in memories.list(
                campaign_id,
                branch_id=branch_id,
                include_inactive=True,
            )
        }
        for index, fact in enumerate(facts_data):
            action = str(fact.get("action", "upsert"))
            if action == "upsert" and current_facts.get(str(fact.get("fact_key", ""))):
                if fact.get("expected_revision_id") is None:
                    raise ValueError(
                        f"payload.facts[{index}].expected_revision_id is required "
                        "when upsert revises a fact"
                    )
            if action == "revise" and fact.get("expected_revision_id") is None:
                raise ValueError(
                    f"payload.facts[{index}].expected_revision_id is required for revisions"
                )
            if "valid_from" in fact:
                fact["valid_from"] = optional_datetime(
                    fact.get("valid_from"), f"facts[{index}].valid_from"
                )
            if "valid_to" in fact:
                fact["valid_to"] = optional_datetime(
                    fact.get("valid_to"), f"facts[{index}].valid_to"
                )
        for index, item in enumerate(knowledge_data):
            if (
                str(item.get("action", "add")) == "revise"
                and item.get("expected_revision_id") is None
            ):
                raise ValueError(
                    "payload.actor_knowledge"
                    f"[{index}].expected_revision_id is required for revisions"
                )
        campaign = campaigns.get(campaign_id)
        if expected_revision is not None and campaign.revision != expected_revision:
            raise ValueError(
                f"campaign revision conflict: expected {expected_revision}, "
                f"found {campaign.revision}"
            )
        response = continuity_commits.commit(
            campaign_id,
            event=event_data,
            facts=facts_data,
            actor_knowledge=knowledge_data,
            snapshot=snapshot_data,
            branch_id=branch_id,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=request_payload,
                response=lambda result: {
                    **result,
                    "skill_manifest": manifest,
                },
            ),
        )
        response["skill_manifest"] = manifest
        return response

    @mcp.tool()
    def module_import_job_create(
        campaign_id: str,
        artifact: str,
        title: str | None = None,
        source_key: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Create a staged module package job before parsing or activating a revision."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for an import job")
        path = storage.artifact_module_path(artifact)
        logical_key = str(source_key or artifact).strip()
        payload = {
            "artifact": artifact,
            "title": title or path.stem,
            "source_key": logical_key,
        }
        scope = f"import-job-create:{campaign_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        document = normalize_document(
            path,
            ocr_provider=storage.module_document_ocr_provider(),
            cache_dir=config.normalized_modules_dir,
            layout_profile=DND5E_DOCUMENT_LAYOUT_PROFILE,
        )
        document_inspection = inspect_character_document(
            document,
            source_name=path.name,
        )
        if document_inspection["document_kind"] != "unknown":
            raise ValueError(
                "character sheets and ability-score option documents are not modules; "
                "use character_query(view='document')"
            )
        preview = modules.preview_path(
            path,
            parser=MarkdownModuleParser(profile=DndModuleProfile()),
            **module_document_options(document.checksum),
        )
        job = import_jobs.create(
            campaign_id=campaign_id,
            kind="module",
            artifact=artifact,
            artifact_checksum=str(preview.get("checksum") or ""),
            payload=payload,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {"job": import_job_view(result)},
            ),
        )
        return {"job": import_job_view(job)}

    @mcp.tool()
    def module_import_job_inspect(
        campaign_id: str,
        job_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Persist parser preview, stable scene keys, and space evidence for a module job."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for module inspection")
        job = require_import_job(campaign_id, job_id, "module")
        payload = {"job_id": job_id, "operation": "inspect"}
        scope = f"import-job:{campaign_id}:{job_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        preview = modules.preview_path(
            storage.artifact_module_path(job.artifact),
            parser=MarkdownModuleParser(profile=DndModuleProfile()),
            **module_document_options(job.artifact_checksum),
        )
        updated = import_jobs.record_inspection(
            job_id,
            preview,
            expected_revision=job.revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {
                    "job": import_job_view(result),
                    "preview": preview,
                },
            ),
        )
        return {"job": import_job_view(updated), "preview": preview}

    @mcp.tool()
    def module_import_job_validate(
        campaign_id: str,
        job_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Validate a staged module and preview scene/progress impact before importing it."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for module validation")
        job = require_import_job(campaign_id, job_id, "module")
        payload = {"job_id": job_id, "operation": "validate"}
        scope = f"import-job:{campaign_id}:{job_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        if job.state not in {"inspected", "validated", "failed"}:
            raise ValueError("module import job must be inspected before validation")
        preview = dict(job.inspection)
        diff = modules.diff_preview(
            campaign_id,
            source_key=str(job.payload.get("source_key") or job.artifact),
            preview=preview,
        )
        diff_ruling_requirements: list[dict[str, Any]] = []
        for impact in diff.get("progress_impact", []):
            if impact.get("action") != "needs_dm_review":
                continue
            reason = (
                "The active module revision removed the scene referenced by "
                f"progress scope {impact.get('scope_id')}; decide its source-backed remap."
            )
            requirement = _ruling_requirement(reason, "source_or_scene_fact")
            impact["ruling_requirement"] = requirement
            diff_ruling_requirements.append(
                {
                    "scope_id": impact.get("scope_id"),
                    "scene_id": impact.get("scene_id"),
                    **requirement,
                }
            )
        validation = {
            "valid": bool(preview.get("valid")),
            "errors": list(preview.get("errors") or []),
            "warnings": list(preview.get("warnings") or []),
            "preview": preview,
            "diff": diff,
            "ruling_requirements": diff_ruling_requirements,
        }
        updated = import_jobs.record_validation(
            job_id,
            validation,
            state="validated" if validation["valid"] else "failed",
            expected_revision=job.revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {
                    "job": import_job_view(result),
                    "validation": validation,
                },
            ),
        )
        return {"job": import_job_view(updated), "validation": validation}

    @mcp.tool()
    def module_import_job_import(
        campaign_id: str,
        job_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Ingest a validated module inactive, preserving the current active module."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for module import")
        job = require_import_job(campaign_id, job_id, "module")
        payload = {"job_id": job_id, "operation": "import"}
        scope = f"import-job:{campaign_id}:{job_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        if job.state not in {"validated", "imported"} or not job.validation.get("valid"):
            raise ValueError("module import job must pass validation before import")
        values = dict(job.payload)
        embedder, vectors = storage.dense_components()
        result = modules.ingest_path(
            campaign_id=campaign_id,
            path=storage.artifact_module_path(job.artifact),
            source_key=str(values.get("source_key") or job.artifact),
            title=str(values.get("title") or job.artifact),
            parser=MarkdownModuleParser(profile=DndModuleProfile()),
            embedder=embedder,
            vector_store=vectors,
            activate=False,
            logical_source_key=str(values.get("source_key") or job.artifact),
            **module_document_options(job.artifact_checksum),
        )
        updated = import_jobs.record_result(
            job_id,
            {**dict(job.result), "module_import": asdict(result)},
            state="imported",
            module_id=result.module_id,
            expected_revision=job.revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda updated_job: {
                    "job": import_job_view(updated_job),
                    **asdict(result),
                },
            ),
        )
        return {"job": import_job_view(updated), **asdict(result)}

    @mcp.tool()
    def module_import_job_activate(
        campaign_id: str,
        job_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
        progress_remaps: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        """Atomically promote an imported module revision after its diff was reviewed."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_write_contract(expected_revision, idempotency_key)
        job = require_import_job(campaign_id, job_id, "module")
        normalized_remaps: list[dict[str, str]] = []
        remap_targets: dict[str, str] = {}
        for index, raw in enumerate(progress_remaps or []):
            if not isinstance(raw, dict):
                raise ValueError(f"progress_remaps[{index}] must be an object")
            unknown = set(raw) - {"from_scene_id", "to_scene_id", "reason"}
            if unknown:
                raise ValueError(
                    f"progress_remaps[{index}] has unsupported fields: {sorted(unknown)}"
                )
            source_scene_id = str(raw.get("from_scene_id") or "").strip()
            target_scene_id = str(raw.get("to_scene_id") or "").strip()
            reason = str(raw.get("reason") or "").strip()
            if not source_scene_id or not target_scene_id:
                raise ValueError(f"progress_remaps[{index}] requires from_scene_id and to_scene_id")
            if not reason or len(reason) > 1000:
                raise ValueError(
                    f"progress_remaps[{index}].reason must contain 1 to 1000 characters"
                )
            if source_scene_id in remap_targets:
                raise ValueError("progress_remaps contains duplicate from_scene_id values")
            remap_targets[source_scene_id] = target_scene_id
            normalized_remaps.append(
                {
                    "from_scene_id": source_scene_id,
                    "to_scene_id": target_scene_id,
                    "reason": reason,
                    "resolver": "agent",
                }
            )
        payload = {
            "job_id": job_id,
            "operation": "activate",
            "module_id": job.module_id,
            "progress_remaps": normalized_remaps,
        }
        scope = f"import-job:{campaign_id}:{job_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        if job.state not in {"imported", "activated"} or not job.module_id:
            raise ValueError("module import job must be imported before activation")
        campaign_scope = f"{scope}:campaign-state"
        campaign_key = f"{idempotency_key}:campaign-state"
        campaign_payload = {**payload, "revision_reason": "module.activation"}
        campaign_replay = idempotency.lookup(
            campaign_scope,
            campaign_key,
            campaign_payload,
        )
        before = None
        if campaign_replay is None:
            before = campaigns.get(campaign_id)
            if dict(before.state or {}).get("combat", {}).get("active", False):
                raise CombatEngineError("module activation cannot change during active combat")
            if before.revision != expected_revision:
                raise ValueError(f"campaign revision conflict: {campaign_id}")

        module_scope = f"{scope}:module-source"
        module_key = f"{idempotency_key}:module-source"
        module_payload = {
            "module_id": job.module_id,
            "operation": "activate",
            "progress_remaps": normalized_remaps,
        }
        module_replay = idempotency.lookup(module_scope, module_key, module_payload)
        if module_replay is not None:
            activation = dict(module_replay.response or {}).get("activation")
        else:
            activation = modules.activate_candidate(
                campaign_id,
                job.module_id,
                progress_remaps=remap_targets,
                idempotency_key=module_key,
                idempotency_write=IdempotencyWrite(
                    scope=module_scope,
                    payload=module_payload,
                    response=lambda result: {"activation": result},
                ),
            )
        if not isinstance(activation, dict):
            raise RuntimeError("module activation replay is malformed")
        activation = {
            **activation,
            "progress_remap_rulings": normalized_remaps,
        }

        if campaign_replay is not None:
            campaign_revision = int(
                dict(campaign_replay.response or {}).get("campaign_revision", 0) or 0
            )
            if campaign_revision < 1:
                raise RuntimeError("module campaign-state replay is malformed")
        else:
            assert before is not None
            state = validate_party_state(dict(before.state or {}))
            after = campaigns.update_audited(
                campaign_id,
                state=state,
                expected_revision=expected_revision,
                operation="module.import.activate",
                actor=principal_id,
                branch_id=current_branch_id(campaign_id),
                idempotency_key=campaign_key,
                request_hash=request_hash(campaign_payload),
                idempotency_write=IdempotencyWrite(
                    scope=campaign_scope,
                    payload=campaign_payload,
                    response=lambda result: {
                        "campaign_revision": result.revision,
                    },
                ),
            )
            campaign_revision = after.revision
        updated = import_jobs.record_result(
            job_id,
            {
                **dict(job.result),
                "activation": activation,
                "campaign_revision": campaign_revision,
            },
            state="activated",
            module_id=job.module_id,
            expected_revision=job.revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda updated_job: {
                    "job": import_job_view(updated_job),
                    "activation": activation,
                    "campaign_revision": campaign_revision,
                },
            ),
        )
        response = {
            "job": import_job_view(updated),
            "activation": activation,
            "campaign_revision": campaign_revision,
        }
        return response

    @mcp.tool()
    def module_write(
        name: str, content: str, principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID
    ) -> dict[str, str]:
        """Write generated Markdown to the managed artifact directory before importing it."""
        if not principal_id:
            raise PermissionError("authenticated caller identity is required for module artifacts")
        path = storage.write_module(name, content)
        return {"artifact": path.name, "path": str(path)}

    @mcp.tool()
    def module_inspect(
        artifact: str, principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID
    ) -> dict[str, Any]:
        """Inspect a managed PDF/Markdown/text artifact before campaign import."""
        if not principal_id:
            raise PermissionError("authenticated caller identity is required for module artifacts")
        return modules.inspect_path(
            storage.artifact_module_path(artifact),
            parser=MarkdownModuleParser(profile=DndModuleProfile()),
            **module_document_options(),
        )

    @mcp.tool()
    def module_import_legacy(
        campaign_id: str,
        artifact: str,
        title: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Import a managed module artifact into a campaign."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for module import")
        payload = {"artifact": artifact, "title": title}
        scope = f"module-import:{campaign_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        path = storage.artifact_module_path(artifact)
        embedder, vectors = storage.dense_components()
        result = modules.ingest_path(
            campaign_id=campaign_id,
            path=path,
            title=title,
            parser=MarkdownModuleParser(profile=DndModuleProfile()),
            embedder=embedder,
            vector_store=vectors,
            **module_document_options(),
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda value: asdict(value),
            ),
        )
        return asdict(result)

    @mcp.tool()
    def module_list(
        campaign_id: str, principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID
    ) -> list[dict[str, Any]]:
        """List a campaign's imported modules."""
        membership = access.require_campaign(campaign_id, principal_id)
        rows = modules.list(campaign_id)
        if membership.role in CAMPAIGN_DM_ROLES:
            return rows
        return [
            {key: value for key, value in row.items() if key not in {"source_path", "metadata"}}
            for row in rows
        ]

    @mcp.tool()
    def module_index(
        campaign_id: str,
        module_id: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> list[dict[str, Any]]:
        """Return a stable scene index for scene selection and safe progression."""
        membership = access.require_campaign(campaign_id, principal_id)
        index = modules.scene_index(campaign_id, module_id=module_id)
        if membership.role in CAMPAIGN_DM_ROLES:
            return index
        return [
            item
            for item in index
            if item.get("visibility", "keeper") in PLAYER_MODULE_VISIBILITY_SCOPES
        ]

    @mcp.tool()
    def module_expand(
        chunk_id: str, principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID
    ) -> dict[str, Any]:
        """Read a complete module chunk after it was selected by search."""
        result = modules.expand(chunk_id)
        membership = access.require_campaign(result["campaign_id"], principal_id)
        visibility = result.get("scene", {}).get("visibility", "keeper")
        if membership.role in CAMPAIGN_DM_ROLES or visibility in PLAYER_MODULE_VISIBILITY_SCOPES:
            return result
        return {
            "chunk_id": result["chunk_id"],
            "campaign_id": result["campaign_id"],
            "redacted": True,
            "content": "[DM-only module content hidden]",
        }

    def module_assets(
        campaign_id: str,
        module_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> list[dict[str, Any]]:
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        return modules.list_assets(campaign_id, module_id)

    def module_asset_attach(
        campaign_id: str,
        module_id: str,
        source_path: str,
        *,
        asset_kind: str,
        scene_id: str | None = None,
        location_key: str | None = None,
        title: str | None = None,
        metadata: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Attach an allowlisted image or support document to an imported module."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for module asset attachment")
        kind = str(asset_kind).strip()
        if not kind or len(kind) > 80:
            raise ValueError("asset_kind must be a non-empty string of at most 80 characters")
        if metadata is not None and not isinstance(metadata, dict):
            raise ValueError("metadata must be an object")
        metadata_value = dict(metadata or {})
        modules.list_assets(campaign_id, module_id)
        if scene_id:
            scene = modules.read_scene(campaign_id, scene_id)
            if scene["module_id"] != module_id:
                raise ValueError("scene_id does not belong to module_id")
        staged = storage.stage_module_asset(module_id, source_path)
        payload = {
            "module_id": module_id,
            "source_checksum": staged["checksum"],
            "asset_kind": kind,
            "scene_id": scene_id,
            "location_key": location_key,
            "title": title,
            "metadata": metadata_value,
        }
        scope = f"module-asset-attach:{campaign_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        asset_metadata = {
            **metadata_value,
            "kind": kind,
            "source_name": Path(source_path).name,
        }
        if title:
            asset_metadata["title"] = str(title)
        if scene_id:
            asset_metadata["scene_id"] = scene_id
        if location_key:
            asset_metadata["location_key"] = str(location_key)
        asset = modules.register_asset(
            campaign_id=campaign_id,
            module_id=module_id,
            source_path=staged["path"],
            media_type=staged["media_type"],
            checksum=staged["checksum"],
            metadata=asset_metadata,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda value: {
                    "campaign_id": campaign_id,
                    "module_id": module_id,
                    "asset": value,
                    "artifact": {
                        key: item for key, item in staged.items() if key not in {"path", "staged"}
                    },
                },
            ),
        )
        response = {
            "campaign_id": campaign_id,
            "module_id": module_id,
            "asset": asset,
            "artifact": {
                key: value for key, value in staged.items() if key not in {"path", "staged"}
            },
        }
        return response

    def module_pdf_asset(
        campaign_id: str,
        module_id: str,
        source_asset_id: str | None = None,
    ) -> dict[str, Any]:
        """Resolve the one checksum-bound PDF used by module page workflows."""

        assets = modules.list_assets(campaign_id, module_id)
        if source_asset_id:
            source_asset = modules.get_asset(campaign_id, source_asset_id)
            if source_asset["module_id"] != module_id:
                raise ValueError("source asset does not belong to module")
        else:
            candidates = [item for item in assets if item["media_type"] == "application/pdf"]
            if len(candidates) != 1:
                raise ValueError("source_asset_id is required unless the module has one PDF asset")
            source_asset = candidates[0]
        if source_asset["media_type"] != "application/pdf":
            raise ValueError("module page workflow requires a PDF source asset")
        if file_sha256(source_asset["source_path"]) != source_asset["checksum"]:
            raise RuntimeError("module PDF no longer matches its imported checksum")
        return source_asset

    @mcp.tool()
    def module_page_render(
        campaign_id: str,
        module_id: str,
        page_number: int,
        source_asset_id: str | None = None,
        scale: float = 1.5,
        include_ocr_text: bool = True,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> Any:
        """Render one imported PDF page as visual evidence for maps or handouts."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        source_asset = module_pdf_asset(campaign_id, module_id, source_asset_id)
        rendered = render_pdf_page(source_asset["source_path"], page_number, scale=scale)
        if rendered.source_checksum != source_asset["checksum"]:
            raise RuntimeError("module PDF no longer matches its imported checksum")
        if not isinstance(include_ocr_text, bool):
            raise ValueError("include_ocr_text must be a boolean")
        ocr_evidence = (
            local_ocr_page_evidence(
                source_asset["source_path"],
                page_number,
                scope="module",
            )
            if include_ocr_text
            else {"included": False}
        )
        target = storage.store_rendered_module_page(
            module_id=module_id,
            source_checksum=rendered.source_checksum,
            page_number=rendered.page_number,
            scale=rendered.scale,
            checksum=rendered.checksum,
            content=rendered.content,
        )
        asset = modules.register_asset(
            campaign_id=campaign_id,
            module_id=module_id,
            source_path=str(target),
            media_type=rendered.media_type,
            checksum=rendered.checksum,
            metadata={
                "kind": "rendered_page",
                "derived_from_asset_id": source_asset["id"],
                "source_checksum": rendered.source_checksum,
                "source_page": rendered.page_number,
                "page_count": rendered.page_count,
                "width": rendered.width,
                "height": rendered.height,
                "scale": rendered.scale,
            },
        )
        return [
            {
                "campaign_id": campaign_id,
                "module_id": module_id,
                "asset": asset,
                "source_asset_id": source_asset["id"],
                "ocr": ocr_evidence,
            },
            Image(path=target),
        ]

    def module_statblock_ocr_recover(
        campaign_id: str,
        module_id: str,
        scene_id: str,
        content_key: str,
        name: str,
        page_number: int,
        source_asset_id: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
        agent_fill: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Recover and review one module statblock without requiring model vision."""

        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        campaign_edition = campaign_rules_edition(campaign_id)
        if campaign_edition != "2014":
            raise ValueError(
                "layout OCR statblock recovery currently supports only D&D 2014; "
                "submit an evidence-bound 2024 transcription through module_review"
            )
        if not idempotency_key:
            raise ValueError("idempotency_key is required for OCR statblock recovery")
        target_name = str(name or "").strip()
        if not 2 <= len(target_name) <= 200:
            raise ValueError("name must contain 2 to 200 characters")
        if isinstance(page_number, bool) or not isinstance(page_number, int) or page_number < 1:
            raise ValueError("page_number must be a positive integer")
        scene = modules.read_scene(campaign_id, scene_id)
        if str(scene.get("module_id") or "") != module_id:
            raise ValueError("OCR statblock recovery scene must belong to the module")
        source_asset = module_pdf_asset(campaign_id, module_id, source_asset_id)
        provider = storage.module_ocr_provider()
        if provider is None or not hasattr(provider, "extract_layout"):
            raise RuntimeError("layout OCR recovery requires the configured RapidOCR provider")

        request_payload = {
            "module_id": module_id,
            "scene_id": scene_id,
            "content_key": content_key,
            "name": target_name,
            "page_number": page_number,
            "source_asset_id": source_asset["id"],
            "source_asset_checksum": source_asset["checksum"],
            "agent_fill": deepcopy(agent_fill),
        }
        scope = f"module-statblock-ocr-recover:{campaign_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay

        recovered_result = recover_pdf_statblock_layout(
            source_path=source_asset["source_path"],
            target_name=target_name,
            candidate_pages=[page_number],
            provider=provider,
        )
        recovered_page = int(recovered_result["page_number"])
        recovered = dict(recovered_result["recovery"])
        normalized_content = str(recovered["normalized_content"])
        parsed = parse_2014_statblock(
            normalized_content,
            source_key=f"module-review:{module_id}:{content_key}",
            name=None,
        )
        agent_fill_requirements = statblock_agent_fill_requirements(parsed.sheet)
        if agent_fill_requirements["required"] and agent_fill is None:
            response = {
                "campaign_id": campaign_id,
                "module_id": module_id,
                "scene_id": scene_id,
                "source_asset_id": source_asset["id"],
                **{
                    key: value
                    for key, value in recovered_result.items()
                    if key != "observation"
                },
                "review": None,
                "requires_agent_fill": True,
                "validation": {
                    "name": parsed.name,
                    "challenge_rating": parsed.challenge_rating,
                    "experience_points": parsed.experience_points,
                    **statblock_settlement(parsed.warnings),
                    "agent_fill": None,
                    "resolved_warnings": [],
                    "agent_fill_requirements": agent_fill_requirements,
                },
            }
            return remember_idempotent(
                scope,
                idempotency_key,
                request_payload,
                response,
                campaign_id=campaign_id,
            )
        reviewed = module_content_review(
            campaign_id,
            module_id,
            scene_id,
            content_key,
            normalized_content,
            str(recovered_result["observation"]),
            source_asset_id=str(source_asset["id"]),
            page_number=recovered_page,
            content_kind="dnd5e_2014_statblock",
            metadata={
                "text_layout_recovery": {
                    "profile": (
                        "rapidocr-layout-"
                        f"v{int(dict(recovered['evidence'])['recovery_version'])}"
                    ),
                    "provider": str(recovered_result["provider"]),
                    "corroboration_mode": str(recovered_result["corroboration_mode"]),
                    "corroboration_scales": list(recovered_result["corroboration_scales"]),
                    "text_only": True,
                }
            },
            principal_id=principal_id,
            idempotency_key=idempotency_key,
            agent_fill=agent_fill,
        )
        response = {
            "campaign_id": campaign_id,
            "module_id": module_id,
            "scene_id": scene_id,
            "source_asset_id": source_asset["id"],
            **{
                key: value
                for key, value in recovered_result.items()
                if key != "observation"
            },
            "requires_agent_fill": False,
            **reviewed,
        }
        return remember_idempotent(
            scope,
            idempotency_key,
            request_payload,
            response,
            campaign_id=campaign_id,
        )

    @mcp.tool()
    def module_content_review(
        campaign_id: str,
        module_id: str,
        scene_id: str,
        content_key: str,
        normalized_content: str,
        observation: str,
        source_asset_id: str | None = None,
        page_number: int | None = None,
        source_chunk_ids: list[str] | None = None,
        content_kind: Literal[
            "dnd5e_2014_statblock",
            "dnd5e_2024_statblock",
        ] = "dnd5e_2014_statblock",
        metadata: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
        agent_fill: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Validate an executable transcription and optional Agent semantic fill."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for module content review")
        campaign_edition = campaign_rules_edition(campaign_id)
        expected_content_kind = statblock_content_kind(campaign_edition)
        if content_kind != expected_content_kind:
            raise ValueError(
                f"content_kind must be {expected_content_kind} for this campaign"
            )
        parsed = parse_edition_statblock(
            normalized_content,
            edition=campaign_edition,
            source_key=f"module-review:{module_id}:{content_key}",
            name=None,
        )
        agent_fill_requirements = require_complete_statblock_agent_fill(
            parsed.sheet,
            agent_fill,
        )
        agent_fill_evidence = reviewed_statblock_fill_evidence(
            campaign_id,
            agent_fill,
            module_id=module_id,
            page_number=page_number,
        )
        metadata_value = deepcopy(dict(metadata or {}))
        if "agent_statblock_fill" in metadata_value:
            raise ValueError("metadata.agent_statblock_fill is reserved; use payload.agent_fill")
        filled = (
            apply_reviewed_statblock_fill(parsed.sheet, agent_fill)
            if agent_fill is not None
            else None
        )
        if filled is not None:
            metadata_value["agent_statblock_fill"] = filled["fill"]
            metadata_value["agent_statblock_fill_evidence"] = agent_fill_evidence
        resolved_warnings = set((filled or {}).get("resolved_warnings") or [])
        retained_warnings = [
            warning for warning in parsed.warnings if warning not in resolved_warnings
        ]
        retained_warnings = list(
            dict.fromkeys(
                [
                    *retained_warnings,
                    *((filled or {}).get("added_warnings") or []),
                ]
            )
        )
        payload = {
            "module_id": module_id,
            "scene_id": scene_id,
            "content_key": content_key,
            "content_kind": content_kind,
            "normalized_content": normalized_content,
            "source_asset_id": source_asset_id,
            "page_number": page_number,
            "source_chunk_ids": source_chunk_ids,
            "observation": observation,
            "metadata": metadata_value,
            "agent_fill": (filled or {}).get("fill"),
        }
        scope = f"module-content-review:{campaign_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        review = modules.review_content(
            campaign_id=campaign_id,
            module_id=module_id,
            scene_id=scene_id,
            content_key=content_key,
            content_kind=content_kind,
            normalized_content=normalized_content,
            source_asset_id=source_asset_id,
            page_number=page_number,
            source_chunk_ids=source_chunk_ids,
            reviewer=principal_id,
            observation=observation,
            metadata=metadata_value,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda value: {
                    "review": value,
                    "validation": {
                        "name": parsed.name,
                        "challenge_rating": parsed.challenge_rating,
                        "experience_points": parsed.experience_points,
                        **statblock_settlement(retained_warnings),
                        "agent_fill": (filled or {}).get("fill"),
                        "resolved_warnings": sorted(resolved_warnings),
                        "agent_fill_requirements": agent_fill_requirements,
                    },
                },
            ),
        )
        response = {
            "review": review,
            "validation": {
                "name": parsed.name,
                "challenge_rating": parsed.challenge_rating,
                "experience_points": parsed.experience_points,
                **statblock_settlement(retained_warnings),
                "agent_fill": (filled or {}).get("fill"),
                "resolved_warnings": sorted(resolved_warnings),
                "agent_fill_requirements": agent_fill_requirements,
            },
        }
        return response

    def module_content_candidates(
        campaign_id: str,
        module_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> list[dict[str, Any]]:
        """Recover review-only statblock candidates from imported text chunks."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        module = next(
            (item for item in modules.list(campaign_id) if str(item.get("id")) == module_id),
            None,
        )
        if module is None:
            raise LookupError(module_id)
        chunks = modules.list_chunks(campaign_id, module_id)
        campaign_edition = campaign_rules_edition(campaign_id)
        candidates = module_statblock_review_candidates(
            chunks,
            source_title=str(module.get("title") or ""),
        )
        for candidate in candidates:
            local_candidate_id = str(candidate["id"])
            candidate["id"] = (
                "candidate:"
                + hashlib.sha256(
                    f"{module_id}\x1f{local_candidate_id}".encode("utf-8")
                ).hexdigest()[:20]
            )
            candidate["review_tool"] = "module_review"
            candidate["review_action"] = "submit_content"
            candidate["module_id"] = module_id
            candidate["content_kind"] = statblock_content_kind(campaign_edition)
            if candidate.get("execution_state") == "review_ready":
                parsed_candidate = parse_edition_statblock(
                    str(candidate.get("normalized_content") or ""),
                    edition=campaign_edition,
                    source_key=f"module-candidate:{candidate['id']}",
                    name=None,
                )
                candidate["agent_fill_requirements"] = statblock_agent_fill_requirements(
                    parsed_candidate.sheet
                )
            if candidate.get("review_status") == "manual_review_required":
                candidate["ruling_requirement"] = _ruling_requirement(
                    str(candidate.get("review_error") or "statblock source needs review"),
                    "missing_or_conflicting_source_review",
                )
            elif candidate.get("execution_state") == "review_ready":
                candidate["ruling_requirement"] = _ruling_requirement(
                    "Review the normalized statblock against its exact module chunks.",
                    "source_or_scene_fact",
                )
            if len(candidate.get("source_scene_ids") or []) != 1:
                candidate["execution_state"] = "blocked"
                candidate["review_status"] = "manual_review_required"
                candidate["review_error"] = (
                    "statblock candidate source chunks must belong to one scene"
                )
                candidate["ruling_requirement"] = _ruling_requirement(
                    candidate["review_error"],
                    "missing_or_conflicting_source_review",
                )
                continue
            candidate["scene_id"] = candidate["source_scene_ids"][0]
        return candidates

    @mcp.tool()
    def module_read_scene(
        campaign_id: str,
        scene_id: str,
        scope_id: str = "party",
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Read one full scene, including its structured rooms and visibility metadata."""
        membership = access.require_campaign(campaign_id, principal_id)
        resolved_scope_id = readable_scene_scope(campaign_id, scope_id, principal_id)
        result = modules.read_scene(campaign_id, scene_id, scope_id=resolved_scope_id)
